# -*- coding: utf-8 -*-
"""ТИПО v4: неизменённая коробка v3 и 61 карта с оригинальными PNG.

Blender 4.3+: Scripting → Open → Run Script.
Встроены утверждённая коробка и исходные изображения. Сеть не требуется.
Существующие сцены сохраняются; создаются две новые сцены с колодой.
"""
import base64
import io
import json
import math
import os
import tempfile
import zipfile
import hashlib
from collections import Counter
from datetime import datetime
from pathlib import Path

import bpy
import numpy as np
from mathutils import Vector, Matrix
from mathutils.geometry import tessellate_polygon

MM = .001
PAPER_HEX = '#FFFCF4'
CARD_SIZE_MM = 65.0
CARD_THICKNESS_MM = .40  # Допущение для текущей демонстрационной стопки из 61 карты.
CARD_GAP_MM = .02
CARD_CORNER_MM = 4.6
STACK_BOTTOM_MM = .37
TOP_SHIFT_Y_MM = .214  # Совмещение по оригиналу «карта в коробке.png».
RENDER_NOW = os.environ.get('TIPO_RENDER', '1') == '1'
RENDER_SIZE = int(os.environ.get('TIPO_RENDER_SIZE', '1400'))
SAMPLES = int(os.environ.get('TIPO_SAMPLES', '128'))
OUTPUT_DIR = Path(os.environ.get('TIPO_OUTPUT_DIR', str(Path.home()/'Downloads'/'TIPO_3D')))
COLORS = ('yellow', 'green', 'blue', 'pink')

def srgb(hex_color):
    return np.array([int(hex_color[i:i + 2], 16) / 255 for i in (1, 3, 5)])

def linear_color(hex_color):
    values = srgb(hex_color)
    linear = np.where(values <= 0.04045, values / 12.92,
                      ((values + 0.055) / 1.055) ** 2.4)
    return (*map(float, linear), 1.0)

def set_input(node, names, value):
    for name in names:
        if name in node.inputs:
            node.inputs[name].default_value = value
            return

def paper_material(name, image=None, color=PAPER_HEX, gloss=True, edge=False):
    material = bpy.data.materials.new(name)
    material.use_nodes = True
    material.diffuse_color = linear_color(color)
    nodes, links = material.node_tree.nodes, material.node_tree.links
    nodes.clear()
    output = nodes.new('ShaderNodeOutputMaterial')
    output.location = (650, 60)
    shader = nodes.new('ShaderNodeBsdfPrincipled')
    shader.location = (340, 60)
    shader.inputs['Base Color'].default_value = linear_color(color)
    shader.inputs['Roughness'].default_value = 0.28 if gloss else 0.62
    shader.inputs['IOR'].default_value = 1.46
    set_input(shader, ('Coat Weight', 'Clearcoat'), 0.42 if gloss else 0.0)
    set_input(shader, ('Coat Roughness', 'Clearcoat Roughness'), 0.18)
    links.new(shader.outputs['BSDF'], output.inputs['Surface'])
    if image:
        texture = nodes.new('ShaderNodeTexImage')
        texture.name = 'Авторский PNG — sRGB, без перекрашивания'
        texture.label = texture.name
        texture.image = image
        texture.interpolation = 'Linear'
        texture.extension = 'EXTEND'
        texture.location = (-430, 220)
        uv_node = nodes.new('ShaderNodeUVMap')
        uv_node.uv_map = 'Авторская развёртка'
        uv_node.location = (-650, 220)
        links.new(uv_node.outputs['UV'], texture.inputs['Vector'])
        links.new(texture.outputs['Color'], shader.inputs['Base Color'])
    geometry = nodes.new('ShaderNodeNewGeometry')
    geometry.location = (-850, -150)
    noise = nodes.new('ShaderNodeTexNoise')
    noise.location = (-600, -150)
    noise.inputs['Scale'].default_value = 14000.0 if edge else 10000.0
    noise.inputs['Detail'].default_value = 2.0
    noise.inputs['Roughness'].default_value = 0.65
    links.new(geometry.outputs['Position'], noise.inputs['Vector'])
    bump = nodes.new('ShaderNodeBump')
    bump.location = (40, -120)
    bump.inputs['Strength'].default_value = 0.14 if edge else 0.075
    bump.inputs['Distance'].default_value = 0.000012 if edge else 0.000006
    links.new(noise.outputs['Fac'], bump.inputs['Height'])
    links.new(bump.outputs['Normal'], shader.inputs['Normal'])
    # Ламинат остаётся гладким: микрорельеф бумаги под глянцевым слоем.
    ramp = nodes.new('ShaderNodeMapRange')
    ramp.location = (-150, -330)
    ramp.inputs['From Min'].default_value = 0.0
    ramp.inputs['From Max'].default_value = 1.0
    ramp.inputs['To Min'].default_value = 0.24 if gloss else 0.55
    ramp.inputs['To Max'].default_value = 0.30 if gloss else 0.72
    links.new(noise.outputs['Fac'], ramp.inputs['Value'])
    links.new(ramp.outputs['Result'], shader.inputs['Roughness'])
    return material

def mesh_object(name, vertices, faces, collection):
    mesh = bpy.data.meshes.new(name)
    mesh.from_pydata(vertices, [], faces)
    mesh.validate()
    mesh.update()
    obj = bpy.data.objects.new(name, mesh)
    collection.objects.link(obj)
    return obj

def prism(name, profile, z0, z1, collection):
    profile = list(profile)
    area = sum(profile[i][0] * profile[(i + 1) % len(profile)][1]
               - profile[(i + 1) % len(profile)][0] * profile[i][1]
               for i in range(len(profile)))
    if area < 0:
        profile.reverse()
    n = len(profile)
    vectors = [Vector((x, y, 0.0)) for x, y in profile]
    triangles = tessellate_polygon([vectors])
    index = {(v.x, v.y): i for i, v in enumerate(vectors)}
    faces = []
    for triangle in triangles:
        # Blender возвращает индексы; поддерживаем и варианты API с Vector.
        ids = tuple(index[(v.x, v.y)] if hasattr(v, 'x') else int(v)
                    for v in triangle)
        faces.extend([tuple(reversed(ids)), tuple(i + n for i in ids)])
    faces += [(i, (i + 1) % n, (i + 1) % n + n, i + n) for i in range(n)]
    vertices = [(x, y, z) for z in (z0, z1) for x, y in profile]
    return mesh_object(name, vertices, faces, collection)


def box_fingerprint(collection):
    record = []
    for obj in sorted(collection.objects, key=lambda o:o.name):
        record.append((obj.name, [tuple(v.co) for v in obj.data.vertices],
                       [(tuple(p.vertices), p.material_index) for p in obj.data.polygons],
                       [[tuple(uv.uv) for uv in layer.data] for layer in obj.data.uv_layers],
                       [m.name for m in obj.data.materials]))
    return hashlib.sha256(repr(record).encode()).hexdigest()


def rounded_profile(size, radius):
    half = size / 2
    points = []
    for cx, cy, start in [(half-radius,half-radius,0),(-half+radius,half-radius,90),
                          (-half+radius,-half+radius,180),(half-radius,-half+radius,270)]:
        for i in range(13):
            a = math.radians(start + i*90/12)
            points.append((cx + radius*math.cos(a), cy + radius*math.sin(a)))
    return points


def artwork_material(key, image):
    material = paper_material('ТИПО • карта • оригинальный PNG • '+key, image=image)
    nodes, links = material.node_tree.nodes, material.node_tree.links
    texture = next(n for n in nodes if n.type == 'TEX_IMAGE')
    shader = next(n for n in nodes if n.type == 'BSDF_PRINCIPLED')
    # Прозрачные скруглённые углы PNG дают цвет бумаги, а не чёрную кайму.
    mix = nodes.new('ShaderNodeMixRGB')
    mix.blend_type = 'MIX'
    mix.inputs[1].default_value = linear_color(PAPER_HEX)
    mix.location = (-60, 220)
    links.new(texture.outputs['Alpha'], mix.inputs[0])
    links.new(texture.outputs['Color'], mix.inputs[2])
    links.new(mix.outputs[0], shader.inputs['Base Color'])
    return material


def load_package():
    encoded = base64.b64decode(PACKAGE_ZIP)
    with zipfile.ZipFile(io.BytesIO(encoded)) as archive:
        if archive.testzip() is not None:
            raise RuntimeError('Повреждён встроенный архив. Скачайте код целиком.')
        metadata = json.loads(archive.read('metadata.json'))
        box_bytes = archive.read('approved_box_v3.blend')
        if hashlib.sha256(box_bytes).hexdigest() != metadata['approved_box_sha256']:
            raise RuntimeError('Контрольная сумма утверждённой коробки не совпала.')
        images = {}
        with tempfile.TemporaryDirectory(prefix='TIPO_cards_v4_') as folder:
            folder = Path(folder)
            box_path = folder/'approved_box_v3.blend'
            box_path.write_bytes(box_bytes)
            names = ('TIPO_Empty_SVG', 'TIPO_Верх_стоя')
            with bpy.data.libraries.load(str(box_path), link=False) as (available, loaded):
                if not all(n in available.scenes for n in names):
                    raise RuntimeError('Встроенная коробка не содержит обе утверждённые сцены.')
                loaded.scenes = list(names)
            flat, upright = loaded.scenes
            flat.name = 'TIPO_61_CARDS_v4'
            upright.name = 'TIPO_61_CARDS_СТОЯ_v4'
            flat.use_fake_user = upright.use_fake_user = True
            for key, info in metadata['artwork'].items():
                data = archive.read(info['archive_name'])
                if hashlib.sha256(data).hexdigest() != info['sha256']:
                    raise RuntimeError('Повреждён исходный PNG: '+info['original_name'])
                image_path = folder/(key+'.png')
                image_path.write_bytes(data)
                image = bpy.data.images.load(str(image_path), check_existing=False)
                image.name = 'TIPO CARDS • оригинал • '+key
                image.colorspace_settings.name = 'sRGB'
                image.alpha_mode = 'STRAIGHT'
                image.pack()
                image.filepath = '//TIPO_CARDS_EMBEDDED/'+key+'.png'
                image.use_fake_user = True
                image['Исходное имя'] = info['original_name']
                image['SHA256 PNG'] = info['sha256']
                images[key] = image
    return flat, upright, images, metadata


def build():
    if bpy.app.version < (4, 3, 0):
        raise RuntimeError('Используйте Blender 4.3 или новее.')
    print('TIPO v4: загружаю утверждённую коробку и оригинальные карты…', flush=True)
    flat, upright, images, metadata = load_package()
    box_flat = next(c for c in flat.collection.children if c.name.startswith('01'))
    box_upright = next(c for c in upright.collection.children if c.name.startswith('01'))
    fingerprints = (box_fingerprint(box_flat), box_fingerprint(box_upright))
    box_images = {i.as_pointer():hashlib.sha256(bytes(i.packed_file.data)).hexdigest()
                  for i in bpy.data.images if i.packed_file and i.name.startswith('TIPO SVG')}
    flat_cards = bpy.data.collections.new('04 • Колода • 60 игровых + правила')
    upright_cards = bpy.data.collections.new('04 • Колода • 61 карта • стоя')
    flat.collection.children.link(flat_cards)
    upright.collection.children.link(upright_cards)
    paper = paper_material('ТИПО • торцы карт • бумага', gloss=False, edge=True)
    materials = {key:artwork_material(key,image) for key,image in images.items()
                 if key not in ('reference','logo_plain','logo_outline')}
    face_numbers = list(range(49,97))+list(range(49,61))
    entries = [('rules_back','rules_front')]+[(COLORS[i%4], 'face_'+str(n))
                                             for i,n in enumerate(face_numbers)]
    assert len(entries) == 61 and entries[-1][0] == 'pink'
    counts = Counter(back for back,_ in entries)
    assert counts == {'yellow':15,'green':15,'blue':15,'pink':15,'rules_back':1}
    transform = Matrix.Translation((0,0,.0335)) @ Matrix.Rotation(math.pi/2,4,'X')
    size, thickness, gap = CARD_SIZE_MM*MM, CARD_THICKNESS_MM*MM, CARD_GAP_MM*MM
    profile = rounded_profile(size, CARD_CORNER_MM*MM)
    for index, (back, face) in enumerate(entries):
        shift = TOP_SHIFT_Y_MM*MM if index == 60 else 0.0
        z0 = STACK_BOTTOM_MM*MM + index*(thickness+gap)
        shifted = [(x,y+shift) for x,y in profile]
        card = prism(f'Карта {index+1:02d} • '+back, shifted, z0, z0+thickness, flat_cards)
        card['deck_index'] = index
        card['back_color'] = back
        card['face_source'] = metadata['artwork'][face]['original_name']
        card['card_complete'] = True
        card['Размер, мм'] = '65 × 65'
        card.data.materials.append(materials[back])
        card.data.materials.append(materials[face])
        card.data.materials.append(paper)
        uv = card.data.uv_layers.new(name='Авторская развёртка')
        for polygon in card.data.polygons:
            top, bottom = polygon.normal.z>.9, polygon.normal.z<-.9
            polygon.material_index = 0 if top else 1 if bottom else 2
            for loop_index in polygon.loop_indices:
                p = card.data.vertices[card.data.loops[loop_index].vertex_index].co
                u, v = p.x/size+.5, (p.y-shift)/size+.5
                uv.data[loop_index].uv = (1-u if bottom else u, v)
        bevel = card.modifiers.new('Мягкий торец карты', 'BEVEL')
        bevel.width = .000015
        bevel.segments = 2
        bevel.limit_method = 'ANGLE'
        bevel.material = 2
        clone = card.copy()
        clone.data = card.data
        upright_cards.objects.link(clone)
        clone.matrix_world = transform @ card.matrix_world
    top = max(v.co.z for v in card.data.vertices)
    flap = next(o for o in box_flat.objects if o.name.startswith('Заправляемый клапан'))
    flap_bottom = min(v.co.z for v in flap.data.vertices)
    if top >= flap_bottom:
        raise RuntimeError('Стопка пересекает клапан. Уменьшите толщину карт или зазор.')
    assert box_fingerprint(box_flat) == fingerprints[0], 'Изменилась утверждённая коробка'
    assert box_fingerprint(box_upright) == fingerprints[1], 'Изменилась стоящая коробка'
    for image in bpy.data.images:
        if image.as_pointer() in box_images:
            assert hashlib.sha256(bytes(image.packed_file.data)).hexdigest()==box_images[image.as_pointer()]
    for scene in (flat,upright):
        scene['Карт внутри'] = 61
        scene['Состав колоды'] = json.dumps(dict(counts),ensure_ascii=False)
        scene['Коробка v3 без изменений'] = True
        scene['Утверждённая коробка SHA256'] = metadata['approved_box_sha256']
        scene['Толщина карты, мм'] = CARD_THICKNESS_MM
        scene['Межкарточный зазор, мм'] = CARD_GAP_MM
        scene['Верхняя карта'] = 'Розовая, целая, сдвиг вверх 0.214 мм по референсу.'
        scene['Лицевые макеты'] = '48 оригиналов 49–96; макеты 49–60 повторены один раз.'
        scene['Авторские PNG загружены'] = True
        scene['Источник коробки'] = 'Утверждённая v3, импортирована без перестроения.'
        scene.render.resolution_x = scene.render.resolution_y = RENDER_SIZE
        scene.render.resolution_percentage = 100
        scene.cycles.samples = SAMPLES
        try:
            import _cycles
            scene.cycles.use_denoising = bool(getattr(_cycles,'with_openimagedenoise',False))
        except ImportError:
            scene.cycles.use_denoising = False
    OUTPUT_DIR.mkdir(parents=True,exist_ok=True)
    stamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    blend_path = OUTPUT_DIR/('TIPO_61_cards_'+stamp+'.blend')
    flat.render.filepath = str(OUTPUT_DIR/('TIPO_61_cards_'+stamp+'.png'))
    upright.render.filepath = str(OUTPUT_DIR/('TIPO_61_cards_top_'+stamp+'.png'))
    if bpy.context.window:
        bpy.context.window.scene = flat
    for screen in bpy.data.screens:
        for area in screen.areas:
            if area.type=='VIEW_3D':
                area.spaces.active.clip_start=.001
                area.spaces.active.clip_end=20
                area.spaces.active.region_3d.view_perspective='CAMERA'
                area.spaces.active.overlay.show_overlays=False
                area.spaces.active.shading.type='MATERIAL'
    bpy.ops.wm.save_as_mainfile(filepath=str(blend_path))
    print('TIPO v4: BLEND: '+str(blend_path),flush=True)
    print('TIPO v4: 61 целая карта; 15/15/15/15 + правила; верхняя розовая.',flush=True)
    print('TIPO v4: коробка и все её текстуры не изменены. Зазор до клапана, мм: '+str((flap_bottom-top)/MM),flush=True)
    if RENDER_NOW:
        bpy.ops.render.render(write_still=True,scene=flat.name)
        print('TIPO v4: PNG: '+flat.render.filepath,flush=True)
    return flat,upright


